-- Model amendments (M6 S5c-2, §4.8 c): the append-only tables `model_amendment` and
-- `model_amendment_withdrawal` (their triggers in 0016), and the unique
-- `(project_id, model_id, id)` on `model_revision` that pins an amendment's base revision
-- to a revision of its own model. Generated by drizzle-kit; the unique constraint moved
-- before the foreign key that needs it.
CREATE TABLE "model_amendment" (
	"id" text PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"model_id" text NOT NULL,
	"element_id" text NOT NULL,
	"via_element_id" text,
	"op" text NOT NULL,
	"before" text,
	"after" text NOT NULL,
	"base_revision_id" text NOT NULL,
	"supersedes_id" text,
	"principal_id" text NOT NULL,
	"client_id" text,
	"source_kind" text NOT NULL,
	"seq" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "model_amendment_project_id_unique" UNIQUE("project_id","id"),
	CONSTRAINT "model_amendment_op_check" CHECK ("model_amendment"."op" in ('call-target', 'message-name', 'event-name', 'process-documentation')),
	CONSTRAINT "model_amendment_humans_only" CHECK ("model_amendment"."source_kind" = 'human')
);
--> statement-breakpoint
CREATE TABLE "model_amendment_withdrawal" (
	"amendment_id" text PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"reason" text NOT NULL,
	"principal_id" text NOT NULL,
	"source_kind" text NOT NULL,
	"seq" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "model_amendment_withdrawal_reason_check" CHECK ("model_amendment_withdrawal"."reason" in ('withdrawn', 'superseded')),
	CONSTRAINT "model_amendment_withdrawal_humans_only" CHECK ("model_amendment_withdrawal"."source_kind" = 'human')
);
